import{_ as o,o as r,c as a,a2 as d}from"./chunks/framework.BLqL3B_z.js";const q=JSON.parse('{"title":"第 3 章 主界面、任务与工作区","description":"> 内容来源：WorkBuddy 官方指南 · 左侧导航栏（非官方整理，© 本指南作者，保留所有权利） 很多新手打开 WorkBuddy 第一眼会懵：左边一条竖排图标，点哪个都不知道干嘛。 这一章带你把最左边那条导航栏彻底搞清楚。它是你所有操作的\\"总入口\\"， 搞懂它，后面 90% 的功能你都能自己找到。","frontmatter":{"title":"第 3 章 主界面、任务与工作区"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 3 章 主界面、任务与工作区/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 3 章 主界面、任务与工作区/index.md","lastUpdated":1791269833000}'),l={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 3 章 主界面、任务与工作区/index.md"};function e(i,t,n,s,u,h){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="第-3-章-workbuddy-的主界面、任务与工作区" tabindex="-1">第 3 章 WorkBuddy 的主界面、任务与工作区 <a class="header-anchor" href="#第-3-章-workbuddy-的主界面、任务与工作区" aria-label="Permalink to &quot;第 3 章 WorkBuddy 的主界面、任务与工作区&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 左侧导航栏（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>很多新手打开 WorkBuddy 第一眼会懵：左边一条竖排图标，点哪个都不知道干嘛。 这一章带你把<strong>最左边那条导航栏</strong>彻底搞清楚。它是你所有操作的&quot;总入口&quot;， 搞懂它，后面 90% 的功能你都能自己找到。</p><h2 id="一、先看懂-导航栏长什么样" tabindex="-1">一、先看懂：导航栏长什么样 <a class="header-anchor" href="#一、先看懂-导航栏长什么样" aria-label="Permalink to &quot;一、先看懂：导航栏长什么样&quot;">​</a></h2><p>导航栏从上到下分成 4 块，记住这个顺序就够了：</p><table tabindex="0"><thead><tr><th>区域</th><th>里面有什么</th><th>白话解释</th></tr></thead><tbody><tr><td>顶部</td><td>版本号、「发现应用」</td><td>看当前版本，顺手发现新应用</td></tr><tr><td>一级入口</td><td>新建任务、助理、项目、专家·技能·连接器、自动化、资料库、更多</td><td>主力功能，点这里进对应页面</td></tr><tr><td>任务与空间</td><td>任务、空间</td><td>你做过的历史任务、工作区列表</td></tr><tr><td>底部</td><td>消息中心、多端协同、账号头像</td><td>消息、设备、账号设置</td></tr></tbody></table><p><strong>为什么先讲这个？</strong> 因为后面每章教的功能（比如&quot;怎么用技能&quot;&quot;怎么连连接器&quot;）， 第一步永远都是&quot;在左边导航栏点 XXX&quot;。你先把入口认熟，后面不用回头找。</p><h2 id="二、一级入口逐个认-这是你每天都会用的" tabindex="-1">二、一级入口逐个认（这是你每天都会用的） <a class="header-anchor" href="#二、一级入口逐个认-这是你每天都会用的" aria-label="Permalink to &quot;二、一级入口逐个认（这是你每天都会用的）&quot;">​</a></h2><ul><li><strong>新建任务</strong>：开启一个本地 AI 工作台，绝大多数活从这里开始。</li><li><strong>助理</strong>：云端助理，可以远程接任务、给你推消息（不在电脑前也能干活）。</li><li><strong>项目</strong>：按项目把任务归类，支持团队协作。</li><li><strong>专家·技能·连接器</strong>：这是&quot;能力中心&quot;——调专家、装技能、连外部服务，后面案例篇重点讲。</li><li><strong>自动化</strong>：设定时任务，让 WorkBuddy 按计划自己跑（比如每周一发周报）。</li><li><strong>资料库</strong>：文档、表格、网页等资料的统一收纳处。</li><li><strong>更多</strong>：低频入口的&quot;收纳盒&quot;——我的邮箱、腾讯文档、ima、乐享知识库、灵感、Genie BaaS。</li></ul><blockquote><p>小提示：入口多了以后，常用的留外面，不常用的收进「更多」，每天少点好几下。</p></blockquote><h2 id="三、动手做-把导航栏调成你顺手的样子" tabindex="-1">三、动手做：把导航栏调成你顺手的样子 <a class="header-anchor" href="#三、动手做-把导航栏调成你顺手的样子" aria-label="Permalink to &quot;三、动手做：把导航栏调成你顺手的样子&quot;">​</a></h2><p>官方允许你自己排菜单顺序。跟着做一遍：</p><ol><li>在左侧导航栏<strong>任意位置点右键</strong>。</li><li>在右键菜单里点 <strong>「自定义菜单」</strong>，会弹出自定义面板。</li><li>面板里有「一级菜单」和「更多」两组： <ul><li><strong>组内排序</strong>：按住条目右边的手柄上下拖，改同一组里的先后。</li><li><strong>跨组移动</strong>：把条目拖到另一组，就能在&quot;一级菜单&quot;和&quot;更多&quot;之间切换。</li></ul></li><li><strong>「新建任务」是固定项</strong>，不能拖，也不能收进「更多」（它是你的主入口，得一直在）。</li><li>拖完<strong>不用点保存</strong>，面板和导航栏同时可见，即时生效；关掉面板配置也会留着，重开客户端还是你排的顺序。</li></ol><p><strong>做完的样子</strong>：你把&quot;新建任务、助理、项目&quot;放一级，剩下的塞进「更多」， 下次打开 WorkBuddy，最常用的三个一眼就能点到。</p><h2 id="四、一个坑-自定义只存在这台电脑上" tabindex="-1">四、一个坑：自定义只存在这台电脑上 <a class="header-anchor" href="#四、一个坑-自定义只存在这台电脑上" aria-label="Permalink to &quot;四、一个坑：自定义只存在这台电脑上&quot;">​</a></h2><p>你调好的顺序<strong>只保存在当前设备</strong>，目前不跨设备同步。 换一台电脑登录，导航栏会按那台电脑自己的设置显示——不是你之前调的。</p><p><strong>应对</strong>：公司/家里两台电脑都用的话，各自调一次；或者把常用功能都放一级菜单， 减少依赖顺序。</p><h2 id="五、本章任务清单-做完就算过关" tabindex="-1">五、本章任务清单（做完就算过关） <a class="header-anchor" href="#五、本章任务清单-做完就算过关" aria-label="Permalink to &quot;五、本章任务清单（做完就算过关）&quot;">​</a></h2><ul><li>[ ] 能说出导航栏 4 块分别是什么</li><li>[ ] 打开「自定义菜单」，把 3 个常用功能拖到一级</li><li>[ ] 确认「新建任务」无法被收进「更多」</li></ul><hr><p><em>下一篇：第 4 章 快速完成第一个 WorkBuddy 任务——用刚才认识的「新建任务」真做一件事。</em></p>',21)])])}const p=o(l,[["render",e]]);export{q as __pageData,p as default};
